import {time,derivative,exactChange,probability,clamp,format} from './math.mjs';
const $=id=>document.getElementById(id);
const dots=Array.from({length:100},()=>{const dot=document.createElement('span');dot.className='person';dot.setAttribute('aria-hidden','true');$('audience').append(dot);return dot;});
let watched=150,x=100,timer=null,draws=[],revealed=0,paused=false,flowTimer=null,guideStep=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function stopSimulation(){clearInterval(timer);timer=null;paused=false;$('pause').disabled=true;$('pause').textContent='Pausar';$('simulate').textContent='▶ Simular 100 usuarios';}
function updateProbability(value=watched){watched=clamp(value,0,200);stopSimulation();draws=[];revealed=0;$('watched').value=watched;$('watched-number').value=watched;$('not-watched').textContent=(200-watched)+' millones';const p=probability(watched),percent=100*p;$('prob-formula').textContent=`${watched} / 200 = ${format(p,3)}`;$('prob-value').innerHTML=`${format(percent,1)}<span>%</span>`;const count=Math.round(percent);dots.forEach((d,i)=>d.className='person'+(i<count?' watched':''));$('watched-count').textContent=count;$('not-count').textContent=100-count;$('sample-status').textContent='PROPORCIÓN DEL MODELO';$('dot-caption').textContent='100 símbolos = 100 % del grupo';$('audience').setAttribute('aria-label',`100 símbolos: aproximadamente ${format(percent,1)} por ciento representan que vieron la película.`);$('sample-progress').textContent='Prueba una muestra aleatoria.';$('observation').innerHTML=`<span class="observation-mark">↗</span><p>El <strong>${format(percent,1)} %</strong> es la probabilidad del modelo. Una muestra aleatoria puede producir una proporción diferente.</p>`;}
function sampleFrame(){if(revealed>=100){stopSimulation();$('sample-status').textContent='MUESTRA COMPLETA';const successes=draws.filter(Boolean).length;$('sample-progress').textContent=`100 usuarios · ${successes} vieron la película.`;$('observation').innerHTML=`<span class="observation-mark">↗</span><p>Modelo: <strong>${format(probability(watched)*100,1)} %</strong>. En esta muestra: <strong>${successes} %</strong>. Cada simulación puede variar; compara varias muestras.</p>`;dots.forEach(d=>d.classList.remove('current'));return;}const batch=reduced.matches?10:2;for(let j=0;j<batch&&revealed<100;j++){dots.forEach(d=>d.classList.remove('current'));const i=revealed++;dots[i].className='person'+(draws[i]?' watched':'')+(i===revealed-1?' current':'');}const successes=draws.slice(0,revealed).filter(Boolean).length;$('watched-count').textContent=successes;$('not-count').textContent=revealed-successes;$('sample-progress').textContent=`${revealed} / 100 usuarios simulados`;$('audience').setAttribute('aria-label',`Muestra en curso: ${revealed} simulados, ${successes} vieron y ${revealed-successes} no vieron.`);if(revealed===100)sampleFrame();}
function startSimulation(){stopSimulation();draws=Array.from({length:100},()=>Math.random()<probability(watched));revealed=0;dots.forEach(d=>d.className='person pending');$('watched-count').textContent='0';$('not-count').textContent='0';$('sample-status').textContent='SIMULACIÓN EN CURSO';$('dot-caption').textContent='Cada símbolo = 1 usuario simulado';$('simulate').textContent='↻ Nueva simulación';$('pause').disabled=false;timer=setInterval(sampleFrame,reduced.matches?100:55);sampleFrame();}
function switchTab(which,focus=false){const isProb=which==='prob';for(const id of ['prob','deriv']){const active=id===which;$(id+'-tab').setAttribute('aria-selected',String(active));$(id+'-tab').tabIndex=active?0:-1;$(id+'-panel').hidden=!active;}if(!isProb){if(timer){clearInterval(timer);timer=null;paused=true;$('pause').textContent='Continuar';}updateDerivative(x);}else stopFlow();$('learning-copy').textContent=isProb?'Mueve el control y compara el porcentaje del modelo con el resultado de una muestra. Una probabilidad no garantiza un resultado exacto en cada simulación.':'T(x) es el tiempo total; T′(x) es una tasa de cambio en ms por solicitud. La tangente aproxima la función cerca del punto elegido. Activa «Vista local» para compararlas.';if(focus)$(which+'-tab').focus();}
function svgNode(tag,attrs,text){const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n;}
function drawGraph(){const local=$('zoom').checked;const xmin=local?Math.max(0,x-15):0;const xmax=local?Math.min(210,x+15):200;const ylo=local?Math.max(0,Math.floor((time(xmin)-8)/10)*10):0;const ymax=local?Math.ceil((time(xmax)+8)/10)*10:450;const X=v=>75+(v-xmin)/(xmax-xmin)*660,Y=v=>300-(v-ylo)/(ymax-ylo)*275;const grid=$('grid');grid.replaceChildren();for(let i=0;i<=5;i++){const yy=ylo+(ymax-ylo)*i/5;grid.append(svgNode('line',{x1:75,x2:735,y1:Y(yy),y2:Y(yy),class:'grid-line'}),svgNode('text',{x:63,y:Y(yy)+4,'text-anchor':'end',class:'tick-label'},format(yy,1)));}for(let i=0;i<=4;i++){const xx=xmin+(xmax-xmin)*i/4;grid.append(svgNode('text',{x:X(xx),y:320,'text-anchor':'middle',class:'tick-label'},format(xx,1)));}let path='';for(let i=0;i<=140;i++){const xx=xmin+(xmax-xmin)*i/140;path+=(i?'L':'M')+X(xx).toFixed(2)+','+Y(time(xx)).toFixed(2)+' ';}$('curve').setAttribute('d',path);const slope=derivative(x);let start=xmin,end=xmax;if(slope>0){start=Math.max(start,x+(ylo-time(x))/slope);end=Math.min(end,x+(ymax-time(x))/slope);}$('tangent').setAttribute('d',`M${X(start)},${Y(time(x)+slope*(start-x))} L${X(end)},${Y(time(x)+slope*(end-x))}`);$('point').setAttribute('cx',X(x));$('point').setAttribute('cy',Y(time(x)));$('crosshair').setAttribute('x1',X(x));$('crosshair').setAttribute('x2',X(x));$('crosshair').setAttribute('y1',Y(time(x)));$('crosshair').setAttribute('y2',300);$('point-label').setAttribute('x',X(x)+(x>160&&!local?-12:12));$('point-label').setAttribute('y',Math.max(19,Y(time(x))-13));$('point-label').setAttribute('text-anchor',x>160&&!local?'end':'start');$('point-label').textContent=`(${x}; ${format(time(x))} ms)`;$('graph').setAttribute('aria-label',`Tiempo T(x)=0,01x²+0,2x+1. Punto elegido: ${x} solicitudes, ${format(time(x))} ms. Pendiente de la tangente: ${format(slope)} ms por solicitud. ${local?'Vista ampliada alrededor del punto.':'Vista general de 0 a 200 solicitudes.'}`);}
function updateDerivative(value=x){x=clamp(value,0,200);$('requests').value=x;$('requests-number').value=x;$('time-value').innerHTML=`${format(time(x))} <small>ms</small>`;$('rate-value').innerHTML=`${format(derivative(x))} <small>ms/solicitud</small>`;$('load-x').textContent=x;$('load-time').textContent=format(time(x));$('approx-value').textContent=format(derivative(x))+' ms';$('exact-value').textContent=format(exactChange(x))+' ms';$('deriv-observation').innerHTML=`Cerca de ${x} solicitudes, una solicitud más añade aproximadamente <strong>${format(derivative(x))} ms</strong> al tiempo del modelo.`;document.querySelectorAll('[data-x]').forEach(b=>{const active=Number(b.dataset.x)===x;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});drawGraph();}
function stopFlow(){clearTimeout(flowTimer);$('load-scene').classList.remove('is-flowing');$('animate-load').textContent='▶';$('animate-load').setAttribute('aria-label','Animar el recorrido de solicitudes');}
$('watched').addEventListener('input',e=>updateProbability(e.target.value));$('watched-number').addEventListener('change',e=>updateProbability(e.target.value));$('simulate').addEventListener('click',startSimulation);$('pause').addEventListener('click',()=>{if(paused){paused=false;timer=setInterval(sampleFrame,reduced.matches?100:55);$('pause').textContent='Pausar';$('sample-status').textContent='SIMULACIÓN EN CURSO';}else{clearInterval(timer);timer=null;paused=true;$('pause').textContent='Continuar';$('sample-status').textContent='SIMULACIÓN EN PAUSA';}});
for(const id of ['prob','deriv']){$(id+'-tab').addEventListener('click',()=>switchTab(id));$(id+'-tab').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();switchTab(e.key==='Home'?'prob':e.key==='End'?'deriv':id==='prob'?'deriv':'prob',true);}});}
$('requests').addEventListener('input',e=>updateDerivative(e.target.value));$('requests-number').addEventListener('change',e=>updateDerivative(e.target.value));$('zoom').addEventListener('change',drawGraph);document.querySelectorAll('[data-x]').forEach(b=>b.addEventListener('click',()=>updateDerivative(b.dataset.x)));
$('animate-load').addEventListener('click',()=>{if($('load-scene').classList.contains('is-flowing')){stopFlow();return;}$('load-scene').classList.add('is-flowing');$('animate-load').textContent='Ⅱ';$('animate-load').setAttribute('aria-label','Pausar la animación de solicitudes');flowTimer=setTimeout(stopFlow,8000);});
$('presentation').addEventListener('click',()=>{const on=document.body.classList.toggle('presentation-mode');$('presentation').innerHTML=on?'Salir de exposición <span aria-hidden="true">↙</span>':'Modo exposición <span aria-hidden="true">↗</span>';$('presentation').setAttribute('aria-pressed',String(on));$('laboratorio').scrollIntoView({behavior:'auto'});});
$('reset-all').addEventListener('click',()=>{updateProbability(150);$('zoom').checked=false;updateDerivative(100);stopFlow();document.querySelectorAll('[data-answer]').forEach(b=>{b.classList.remove('correct','incorrect');b.removeAttribute('aria-pressed');});$('quiz-feedback').textContent='Selecciona una respuesta para comprobar tu interpretación.';});
document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-answer]').forEach(c=>{c.classList.remove('correct','incorrect');c.setAttribute('aria-pressed','false');});b.setAttribute('aria-pressed','true');const right=b.dataset.answer==='rate';b.classList.add(right?'correct':'incorrect');$('quiz-feedback').textContent=right?'Correcto. 2,2 ms/solicitud es la tasa de cambio local. El tiempo total del modelo en 100 solicitudes es 121 ms.':'Inténtalo de nuevo. La prima (′) indica una derivada: mide el cambio del tiempo por solicitud, no el tiempo total ni una probabilidad.';}));
const guide=[['Empieza por una proporción.','De 200 millones del ejemplo, 150 vieron la película. Divide 150 entre 200: la probabilidad es 0,75, o 75 %.'],['La muestra puede variar.','Mueve el control y pulsa «Simular 100 usuarios». Compara el porcentaje del modelo con los resultados observados. Repite para ver la variación aleatoria.'],['Ahora cambia la carga.','En Derivada, mueve el número de solicitudes. La curva roja muestra T(x), el tiempo total; la recta azul muestra la pendiente local T′(x). Activa «Vista local» para acercarte al punto.'],['Interpreta antes de concluir.','En x = 100, T(100) = 121 ms y T′(100) = 2,2 ms/solicitud. Pasar a 101 solicitudes suma exactamente 2,21 ms: la derivada da una aproximación cercana.']];
function updateGuide(){$('guide-title').textContent=guide[guideStep][0];$('guide-copy').textContent=guide[guideStep][1];$('guide-counter').textContent=`RECORRIDO · 0${guideStep+1} / 04`;$('guide-prev').disabled=guideStep===0;$('guide-next').textContent=guideStep===3?'Explorar por mi cuenta →':'Siguiente →';switchTab(guideStep<2?'prob':'deriv');}
$('guide-open').addEventListener('click',()=>{guideStep=0;updateGuide();$('guide').showModal();});$('guide-prev').addEventListener('click',()=>{if(guideStep>0){guideStep--;updateGuide();}});$('guide-next').addEventListener('click',()=>{if(guideStep===3){$('guide').close();$('laboratorio').scrollIntoView();}else{guideStep++;updateGuide();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(timer){clearInterval(timer);timer=null;paused=true;$('pause').textContent='Continuar';$('sample-status').textContent='SIMULACIÓN EN PAUSA';}stopFlow();}});
$('watched-number').addEventListener('input',e=>{if(e.target.value!=='')updateProbability(e.target.value);});
$('requests-number').addEventListener('input',e=>{if(e.target.value!=='')updateDerivative(e.target.value);});
updateProbability();updateDerivative();
